const items = [];
for (let i = 1; i <= 15; i++) {
  items.push({ json: { lead_id: i, to_number: '+1555000' + String(100 + i), note: 'mock only' } });
}
return items;

const items = $input.all();
const counts = {};
let found = 0;
for (const it of items) {
  const j = it.json || {};
  const sources = [j.headers, j.body && j.body.headers, j.data && typeof j.data === 'object' ? j.data.headers : null];
  let trace = null;
  for (const h of sources) {
    if (h && typeof h === 'object') {
      trace = h['X-Amzn-Trace-Id'] || h['x-amzn-trace-id'];
      if (trace) break;
    }
  }
  if (!trace) continue;
  const m = /Root=1-([0-9a-fA-F]{8})/.exec(String(trace));
  if (!m) continue;
  const sec = parseInt(m[1], 16);
  counts[sec] = (counts[sec] || 0) + 1;
  found++;
}
if (found === 0) {
  return [{ json: { error: 'trace header not found', sample: items[0] ? Object.keys(items[0].json || {}) : [] } }];
}
const max = Math.max(...Object.values(counts));
return [{ json: { total_requests: found, requests_per_second: counts, max_per_second: max, limit: 5, pass: max <= 5 } }];
